// Server-side loader for the companion control token.
//
// The token lives at `<root>/.builder/eliza/control.token`: an owned, regular, 0600
// file inside a 0700 parent, generated by the companion itself
// (builder/eliza/src/main.mjs). It is loaded by the HOST at runtime-init only, is
// opened with O_NOFOLLOW (no symlink swap), read into a bounded buffer, and is never
// logged or returned to any non-host caller, the view bundle, or character settings.

import { open, stat } from "node:fs/promises";
import { constants } from "node:fs";
import path from "node:path";

export const CONTROL_TOKEN_RELATIVE = path.join(".builder", "eliza", "control.token");
const MIN_LEN = 16;
const MAX_LEN = 256;
const TOKEN_PATTERN = /^[A-Za-z0-9._-]+$/;
const OPEN_FLAGS = constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0) | (constants.O_NONBLOCK ?? 0);

export function resolveControlTokenPath(root) {
  if (typeof root !== "string" || !root.trim()) {
    throw new Error("companion root is required to locate the control token");
  }
  return path.join(path.resolve(root), CONTROL_TOKEN_RELATIVE);
}

function isPrivate(mode) {
  return (mode & 0o077) === 0;
}

/**
 * Load the control token, or `null` when it is missing, non-regular, symlinked,
 * not owned by this process, or not private (0600 in a 0700 parent).
 */
export async function loadControlToken(options = {}) {
  const root = options.root ?? process.env.PHP_RETRO_BUILDER_ROOT;
  if (!root) return null;
  let tokenPath;
  try {
    tokenPath = resolveControlTokenPath(root);
  } catch {
    return null;
  }

  try {
    const parent = await stat(path.dirname(tokenPath));
    if (!parent.isDirectory() || !isPrivate(parent.mode)) return null;
  } catch {
    return null;
  }

  let handle;
  try {
    handle = await open(tokenPath, OPEN_FLAGS);
  } catch {
    return null;
  }
  try {
    const info = await handle.stat();
    if (!info.isFile()) return null;
    if (!isPrivate(info.mode)) return null;
    if (typeof process.getuid === "function" && info.uid !== process.getuid()) return null;
    const buffer = Buffer.alloc(MAX_LEN + 1);
    const { bytesRead } = await handle.read(buffer, 0, buffer.length, 0);
    if (bytesRead <= 0 || bytesRead > MAX_LEN) return null;
    const raw = buffer.subarray(0, bytesRead).toString("utf8").trim();
    if (raw.length < MIN_LEN || raw.length > MAX_LEN) return null;
    if (!TOKEN_PATTERN.test(raw)) return null;
    return raw;
  } catch {
    return null;
  } finally {
    await handle.close().catch(() => {});
  }
}
